#!/usr/bin/env python3
import base64, gzip, hashlib, pathlib, subprocess, sys, tempfile

PATCH_B64 = ""

EXPECTED = {
    "iTorrent/Screens/TorrentList/TorrentListViewController.swift": "3eda82063788ac34b007244ad45967d0e0a588d4b1f62d133e4260b4761ac67b",
    "iTorrent.xcodeproj/project.pbxproj": "752f4a4207cd410856922f252c5836e969de41047c8ae3ae4811dc0ad2f31f04",
}

def sha256(path: pathlib.Path) -> str:
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()

def main() -> int:
    root = pathlib.Path.cwd()
    for rel, expected in EXPECTED.items():
        path = root / rel
        actual = sha256(path)
        if actual != expected:
            raise RuntimeError(f"V0.1.5 stable baseline mismatch: {rel} sha256={actual}, expected={expected}")

    patch = gzip.decompress(base64.b64decode(PATCH_B64))
    with tempfile.NamedTemporaryFile(prefix='btmobile-v016-', suffix='.patch', delete=False) as f:
        f.write(patch)
        patch_path = pathlib.Path(f.name)

    try:
        subprocess.run(['git', 'apply', '--check', str(patch_path)], cwd=root, check=True)
        subprocess.run(['git', 'apply', str(patch_path)], cwd=root, check=True)
    finally:
        patch_path.unlink(missing_ok=True)

    project = (root / 'iTorrent.xcodeproj/project.pbxproj').read_text(encoding='utf-8')
    source = (root / 'iTorrent/Screens/TorrentList/TorrentListViewController.swift').read_text(encoding='utf-8')
    if 'MARKETING_VERSION = 0.1.6;' not in project or 'CURRENT_PROJECT_VERSION = 17;' not in project:
        raise RuntimeError('V0.1.6 version metadata not applied')
    for marker in ('final class BTImageViewerViewController', 'final class BTTextEditorViewController', 'var isImage: Bool', 'var isEditableText: Bool'):
        if marker not in source:
            raise RuntimeError(f'V0.1.6 source marker missing: {marker}')
    print('V0.1.6 file-manager patch applied successfully')
    return 0

if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f'apply_v016 failed: {exc}', file=sys.stderr)
        raise
